using System;using System.IO;using System.Text;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;
namespace IslandIntegrated {
 // Explicitly approved local credential owner. Only fixed DeepSeek balance GET;
 // never logs keys/configuration/headers, installs a service or opens a listener.
 public sealed class LegacyBalanceOwner:IDisposable {
  readonly object gate=new object();readonly CancellationTokenSource stop=new CancellationTokenSource();readonly Func<DateTimeOffset> clock;readonly Func<Uri,CancellationToken,Task<StatusServiceResponse>> supplied;
  BalanceReadonlySnapshot current=new BalanceReadonlySnapshot();DateTimeOffset next=DateTimeOffset.MinValue;bool pending,disposed,denied,seeded,missing;
  public LegacyBalanceOwner(Func<Uri,CancellationToken,Task<StatusServiceResponse>> fake=null,Func<DateTimeOffset> utc=null){supplied=fake;clock=utc??(()=>DateTimeOffset.UtcNow);}
  static string ReadSmall(string path,int limit){for(string p=Path.GetFullPath(path);!String.IsNullOrEmpty(p);p=Path.GetDirectoryName(p))if((File.Exists(p)||Directory.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException();try{using(var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)){var bytes=new byte[limit+1];int total=0,n;while(total<bytes.Length&&(n=f.Read(bytes,total,bytes.Length-total))>0)total+=n;if(total>limit)throw new InvalidDataException();return new UTF8Encoding(false,true).GetString(bytes,0,total);}}catch(FileNotFoundException){return null;}catch(DirectoryNotFoundException){return null;}}
  static Dictionary<string,object> Object(string text,int limit){return text==null?null:new JavaScriptSerializer{MaxJsonLength=limit,RecursionLimit=12}.DeserializeObject(text.TrimStart('\uFEFF')) as Dictionary<string,object>;}
  static string S(Dictionary<string,object>d,string k){object v;return d!=null&&d.TryGetValue(k,out v)?v as string:null;}
  public static bool Enabled(string file){try{if(!File.Exists(Path.Combine(Path.GetDirectoryName(Path.GetDirectoryName(file)),"FILE-MANIFEST.json")))return false;var d=Object(ReadSmall(file,4096),4096);object approved,interval;if(d==null||d.Keys.AnyInvalid()||S(d,"schema")!="sidebar.balance-connection.v1"||S(d,"endpoint")!=DeepSeekBalanceAdapter.Endpoint.AbsoluteUri||S(d,"credentialOwner")!="approved-existing-legacy"||!d.TryGetValue("approved",out approved)||!(approved is bool)||!(bool)approved||!d.TryGetValue("refreshSeconds",out interval)||!(interval is int)||(int)interval!=300)return false;return true;}catch{return false;}}
  static string ExistingKey(){string root=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);var cfg=Object(ReadSmall(Path.Combine(root,@"StatusIsland\config.json"),65536),65536);string key=S(cfg,"deepseekApiKey");if(String.IsNullOrWhiteSpace(key))key=Environment.GetEnvironmentVariable("DEEPSEEK_API_KEY");if(String.IsNullOrWhiteSpace(key)){cfg=Object(ReadSmall(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),@".claude\settings.json"),65536),65536);object env;var e=cfg!=null&&cfg.TryGetValue("env",out env)?env as Dictionary<string,object>:null;Uri origin;if(Uri.TryCreate(S(e,"ANTHROPIC_BASE_URL"),UriKind.Absolute,out origin)&&origin.Scheme=="https"&&origin.Host=="api.deepseek.com")key=S(e,"ANTHROPIC_AUTH_TOKEN");}if(String.IsNullOrWhiteSpace(key))return null;key=key.Trim();if(!System.Text.RegularExpressions.Regex.IsMatch(key,"^[A-Za-z0-9_-]{8,512}$"))throw new InvalidDataException();return key;}
  async Task<StatusServiceResponse> Request(Uri endpoint,CancellationToken token){string key=null;try{missing=false;key=ExistingKey();if(key==null){missing=true;return new StatusServiceResponse{Status=401};}var transport=new DeepSeekBalanceHttpTransport(r=>r.Headers[System.Net.HttpRequestHeader.Authorization]="Bearer "+key);return await transport.SendAsync(endpoint,token).ConfigureAwait(false);}finally{key=null;}}
  public BalanceReadonlySnapshot ReadFast(string seedFile,string configuration){if(supplied==null&&!Enabled(configuration))return BalanceReadonlySnapshot.Load(seedFile);lock(gate){if(!seeded){seeded=true;if(!String.IsNullOrEmpty(seedFile)){var seed=BalanceReadonlySnapshot.Load(seedFile);if(seed.Fresh(clock())){current=seed;next=seed.ObservedAt.AddMinutes(5);}}}if(disposed||pending||denied||clock()<next)return current;pending=true;next=clock().AddMinutes(5);Task.Run(async()=>{BalanceReadonlySnapshot value;try{StatusServiceResponse response;using(var limit=CancellationTokenSource.CreateLinkedTokenSource(stop.Token)){limit.CancelAfter(12000);response=await (supplied??new Func<Uri,CancellationToken,Task<StatusServiceResponse>>(Request))(DeepSeekBalanceAdapter.Endpoint,limit.Token).ConfigureAwait(false);}if(response==null)value=new BalanceReadonlySnapshot{State="server-error"};else if(response.Status==200){value=DeepSeekBalanceAdapter.Parse(response.Body,"CNY",clock());if(value.State=="invalid")value=DeepSeekBalanceAdapter.Parse(response.Body,"USD",clock());}else value=new BalanceReadonlySnapshot{State=missing?"not-connected":response.Status==401||response.Status==403?"unauthorized":"server-error"};if(response!=null&&response.RetryAfterSeconds.HasValue)lock(gate){next=clock().AddSeconds(Math.Max(300,response.RetryAfterSeconds.Value));}}
   catch(UnauthorizedAccessException){lock(gate){denied=true;}value=new BalanceReadonlySnapshot{State="access-denied"};}catch{value=new BalanceReadonlySnapshot{State="server-error"};}lock(gate){if(!disposed)current=value;pending=false;}});return current;}}
  public void Dispose(){lock(gate){if(disposed)return;disposed=true;stop.Cancel();}}
 }
 internal static class BalanceConnectionKeys {public static bool AnyInvalid(this IEnumerable<string> keys){foreach(string k in keys)if(k!="schema"&&k!="approved"&&k!="endpoint"&&k!="credentialOwner"&&k!="refreshSeconds"&&k!="approvalReference")return true;return false;}}
}
